  QuizQuestion(id: 'mg9_1_1', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 0,
    questionText: 'Bir resepsiyon görevlisinin otele ilk kez giriş yapan misafiri tebessümle karşılayıp oda kartını takdim etmesi sürecinde; bilgiyi ileten görevli iletişim modelinin hangi temel ögesini temsil eder?',
    options: ['Kaynak (Gönderici)', 'Kanal (Araç)', 'Dönüt (Geri Bildirim)', 'Gürültü (Engeller)'],
    correctOptionIndex: 0,
    explanation: 'İletişim sürecini başlatan, duygu, düşünce veya bilgiyi kodlayarak karşı tarafa aktaran kişi \'Kaynak (Gönderici)\' olarak adlandırılır.',
  ),
  QuizQuestion(id: 'mg9_1_2', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 0,
    questionText: 'Misafir ilişkileri sorumlusunun, otelden ayrılan bir konuğa \'Konaklamanızdan memnun kaldınız mı efendim?\' sorusuna konuğun gülümseyerek başını sallaması, iletişim sürecindeki hangi temel unsura örnektir?',
    options: ['Kod Çözme', 'Dönüt (Geri Bildirim)', 'Mesaj İletim Kanalı', 'Çevresel Gürültü'],
    correctOptionIndex: 1,
    explanation: 'Alıcının kaynağın ilettiği mesaja verdiği her türlü sözlü veya sözsüz yanıta \'Dönüt (Geri Bildirim)\' denir.',
  ),
  QuizQuestion(id: 'mg9_1_3', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 0,
    questionText: 'Bir seyahat acentesinde tur danışmanı ile gezgin arasındaki görüşme sırasında yoldan geçen ağır bir iş makinesinin çıkardığı yüksek ses nedeniyle konuşmaların anlaşılamaması iletişimde ne olarak tanımlanır?',
    options: ['Dönüt Yetersizliği', 'Hedef Kitle Karmaşası', 'Fiziksel Gürültü (İletişim Engeli)', 'Kodlama Eksikliği'],
    correctOptionIndex: 2,
    explanation: 'Mesajın kaynaktan alıcıya iletilmesini zorlaştıran, bozan veya engelleyen çevresel dış sesler fiziksel gürültü kapsamındadır.',
  ),
  QuizQuestion(id: 'mg9_1_4', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 0,
    questionText: 'Bir kat görevlisinin temizlik arabasını koridorda düzenlerken karşılaştığı bir konukla göz teması kurup hafifçe tebessüm etmesi ve dik durması hangi iletişim türünün en etkili yansımasıdır?',
    options: ['Resmi Yazılı İletişim', 'Tek Yönlü İletişim', 'Dijital İletişim', 'Sözsüz İletişim (Beden Dili)'],
    correctOptionIndex: 3,
    explanation: 'Duruş, yüz ifadesi (mimik), el hareketleri (jest) ve göz teması gibi kelimelere başvurulmadan kurulan iletişim \'Sözsüz İletişim\'dir.',
  ),
  QuizQuestion(id: 'mg9_1_5', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 0,
    questionText: 'Uçağı rötar yaptığı için çok yorgun ve gergin olan bir konuğun resepsiyonda öfkeyle serzenişte bulunması karşısında, personelin sözünü kesmeden, göz teması kurarak ve hissettiği yorgunluğu anlayışla onaylayarak dinlemesi hangi beceriyi ifade eder?',
    options: ['Empatik ve Etkin Dinleme', 'Savunmacı Dinleme', 'Seçici Dinleme', 'Görünüşte Dinleme'],
    correctOptionIndex: 0,
    explanation: 'Karşı tarafın duygularını, ihtiyaçlarını ve bakış açısını yargılamadan, tüm dikkati vererek anlamaya çalışmak \'Empatik ve Etkin Dinleme\'dir.',
  ),
  QuizQuestion(id: 'mg9_1_6', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 0,
    questionText: 'Bir servis personelinin sipariş gecikmesi yaşayan konuğa: \'Her şeye çok çabuk sinirleniyorsunuz, mutfağın yoğunluğunu hiç düşünmüyorsunuz!\' demesi hangi yıkıcı dil kalıbına örnektir?',
    options: ['Ben Dili', 'Sen Dili (Suçlayıcı Dil)', 'Çözüm Odaklı İfade', 'Empatik İfade'],
    correctOptionIndex: 1,
    explanation: '\'Sen dili\', kişiyi doğrudan suçlayan, yargılayan ve savunmaya iten; iletişim çatışmalarını körükleyen olumsuz bir üsluptur.',
  ),
  QuizQuestion(id: 'mg9_1_7', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 0,
    questionText: 'Aynı servis personelinin sipariş gecikmesinde: \'Sizi bu kadar beklettiğimiz için mahcubiyet duyuyorum; durumun telafisi için şefimizle görüşüp hemen servis edilmesini sağlıyorum\' demesi hangi iletişim yaklaşımını yansıtır?',
    options: ['Otoriter Dil', 'Pasif Savunma', 'Ben Dili ve Çözüm Odaklı Yaklaşım', 'Görmezden Gelme'],
    correctOptionIndex: 2,
    explanation: 'Kişiyi hedef almadan durumun yarattığı duyguyu ifade eden ve derhal yapıcı çözüm üreten yaklaşım \'Ben Dili\' ve çözüm odaklı iletişimdir.',
  ),
  QuizQuestion(id: 'mg9_1_8', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 0,
    questionText: 'Bir turizm tesisinde kat hizmetleri ile ön büro departmanı arasındaki oda temizlik durumu bildirimlerinin eksikliği nedeniyle konukların hazır olmayan odalara yönlendirilmesi hangi kurumsal iletişim türündeki aksaklıktan kaynaklanır?',
    options: ['Dış İletişim', 'Aşağıdan Yukarıya İletişim', 'Yukarıdan Aşağıya İletişim', 'Yatay (Departmanlar Arası) İletişim'],
    correctOptionIndex: 3,
    explanation: 'Aynı hiyerarşik düzeydeki farklı departman veya çalışanlar arasındaki bilgi akışına \'Yatay İletişim\' denir.',
  ),
  QuizQuestion(id: 'mg9_1_9', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 0,
    questionText: 'Yabancı bir misafire yerel bir deyim veya çok teknik bir mesleki terim kullanılarak açıklama yapılması sonucu konuğun durumu tamamen yanlış anlaması hangi iletişim engeline örnektir?',
    options: ['Semantik (Dil ve Anlam) Engeli', 'Kişisel Engel', 'Fiziksel Kanal Engeli', 'Zaman Kısıtı Engeli'],
    correctOptionIndex: 0,
    explanation: 'Kelimelerin, simgelerin veya deyimlerin farklı kültür ve dillerde farklı anlamlara gelmesinden doğan engellere \'Semantik (Anlamsal) Engeller\' denir.',
  ),
  QuizQuestion(id: 'mg9_1_10', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 0,
    questionText: 'Turizm ve konaklama sektöründe telefonla rezervasyon alırken personelin uyması gereken en temel mesleki nezaket kuralı aşağıdakilerden hangisidir?',
    options: ['Telefonu en az 10 kez çaldırdıktan sonra açmak', 'Telefonu en geç üçüncü çalışta tebessüm eden bir ses tonuyla açıp kurum ve kendi adını söyleyerek selamlamak', 'Arayan kişinin sözünü bitirmeden fiyat listesini hızlıca okumak', 'Görüşmeyi misafirden önce telefonu kapatarak sonlandırmak'],
    correctOptionIndex: 1,
    explanation: 'Telefon iletişiminde profesyonellik; telefonun en geç üçüncü çalışta açılması, ses tonuna tebessümün yansıtılması ve kurum/isim belirterek selamlamayla başlar.',
  ),
  QuizQuestion(id: 'mg9_1_11', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 0,
    questionText: 'Bir otel yöneticisinin çalışanlarına gönderdiği resmi e-postada tüm metni BÜYÜK HARFLERLE yazması dijital iletişim kurallarına (Netiquette) göre nasıl değerlendirilir?',
    options: ['Çok saygılı ve resmi bir hitap biçimi', 'Önemli konuların en doğru iletilme yolu', 'Sanal ortamda \'bağırmak ve öfke göstermek\' anlamına gelen kaba bir davranış', 'Yasal bir zorunluluk'],
    correctOptionIndex: 2,
    explanation: 'Dijital görgü kurallarında (Netiquette) tamamen büyük harflerle yazmak karşı tarafa bağırmak, azarlamak veya öfke kusmak anlamına gelir.',
  ),
  QuizQuestion(id: 'mg9_1_12', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 0,
    questionText: 'İki çalışma arkadaşı arasındaki görev paylaşımı anlaşmazlığında; tarafların her ikisinin de menfaatlerini koruyarak ortak bir noktada uzlaşmaları hangi çatışma çözme stratejisidir?',
    options: ['Kaçınma', 'Zorlama (Hükmetme)', 'Uyum Sağlama (Teslim Olma)', 'İş Birliği Yapma (Kazan-Kazan)'],
