    explanation: 'Her iki tarafın da ihtiyaçlarını karşılayan ve ortak fayda sağlayan yapıcı çatışma çözme stratejisi \'İş Birliği (Kazan-Kazan / Win-Win)\' yöntemidir.',
  ),
  QuizQuestion(id: 'mg9_1_13', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 0,
    questionText: 'Bir kongre organizasyonunda görevli Mihmandarın, yabancı delegasyon üyeleriyle iletişim kurarken kişisel alan sınırlarına (mahremiyet mesafesi) özen göstermesi iletişimin hangi boyutunu oluşturur?',
    options: ['Mekânsal Boyut (Proksemik)', 'Kronemik (Zaman) Boyutu', 'Semiotik Boyut', 'İntrapersonel Boyut'],
    correctOptionIndex: 0,
