  // ÜNİTE 2: MESLEK ETİĞİ VE AHİLİK KÜLTÜRÜ (16 Soru)
  QuizQuestion(id: 'mg9_2_1', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 1,
