  QuizQuestion(id: 'mg9_5_3', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 4,
    questionText: 'Alexander Osterwalder tarafından geliştirilen ve bir işletmenin iş modelini tek bir sayfada 9 temel yapı taşıyla görselleştiren stratejik yönetim aracı hangisidir?',
