  QuizQuestion(id: 'mg9_5_6', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 4,
    questionText: 'Türkiye\'de küçük ve orta ölçekli işletmeler ile yeni girişimcilere hibe, faizsiz kredi ve danışmanlık desteği sağlayan temel kamu kuruluşu hangisidir?',
