  QuizQuestion(id: 'mg9_5_7', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 4,
    questionText: 'Bir işletmenin stratejik durumunu analiz ederken iç çevredeki \'Güçlü ve Zayıf Yönleri\' ile dış çevredeki \'Fırsat ve Tehditleri\' değerlendiren yöntem hangisidir?',
