  QuizQuestion(id: 'mg9_5_10', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 4,
    questionText: 'Girişimcinin ürettiği ürün veya hizmeti tanıtmak, satmak ve dağıtmak için misafir veya tüketicilere ulaştığı temas noktalarına İş Modeli Kanvasında ne denir?',
