  QuizQuestion(id: 'mg9_5_11', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 4,
    questionText: 'Girişimcilikte yüksek risk taşıyan ancak çok hızlı büyüme potansiyeli bulunan teknolojik girişimlere başlangıç aşamasında sermaye ve mentörlük sağlayan bireysel yatırımcılara ne ad verilir?',
