  QuizQuestion(id: 'mg9_5_12', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 4,
    questionText: 'Bir turizm mezununun kurduğu yeni işletmenin toplam gelirlerinin, toplam maliyetlerine (sabit ve değişken giderlerine) tam olarak eşit olduğu, ne kâr ne zarar edilen kritik finansal noktaya ne ad verilir?',
