  QuizQuestion(id: 'mg9_5_13', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 4,
    questionText: 'Tasarım Odaklı Düşünme (Design Thinking) metodolojisinin ilk ve en önemli adımı aşağıdakilerden hangisidir?',
