  ),
  QuizQuestion(id: 'mg9_5_14', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 4,
    questionText: 'Bir işletmenin kira, yönetici maaşları, sigorta primi gibi üretim veya satış miktarından bağımsız olarak her ay düzenli ödemek zorunda olduğu gider türü hangisidir?',
