  ),
  QuizQuestion(id: 'mg9_5_15', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 4,
    questionText: 'Başarılı bir iş modelinde girişimcinin \'Temel Ortaklar\' kutusuna yazması gereken unsurlar aşağıdakilerden hangisidir?',
