  QuizQuestion(id: 'mg9_5_16', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 4,
    questionText: 'Girişimcinin sadece kendi cebindeki sınırlı birikimiyle, dışarıdan borç veya kredi almadan, kazandığı her kuruşu yeniden işe yatırarak büyüme modeline ne denir?',
