  // ÜNİTE 6: FİKRÎ VE SINAİ MÜLKİYET HAKLARI (16 Soru)
  QuizQuestion(id: 'mg9_6_1', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 5,
    questionText: 'Türkiye\'de patent, faydalı model, marka, tasarım ve coğrafi işaretlerin tescili işlemlerini yürüten resmi yetkili kamu kurumu hangisidir?',
    options: ['TÜRKPATENT (Türk Patent ve Marka Kurumu)', 'TÜBİTAK', 'Rekabet Kurumu', 'Kültür Bakanlığı'],
