    explanation: 'Türkiye\'de sınai mülkiyet haklarının tescilini ve korunmasını yürüten kurum \'TÜRKPATENT\'tir.',
  ),
  QuizQuestion(id: 'mg9_6_2', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 5,
    questionText: 'Bir işletmenin mal veya hizmetlerini diğer işletmelerin mal veya hizmetlerinden ayırt etmeyi sağlayan kişi adları, sözcükler, şekiller, harfler ve logolara ne denir?',
