  QuizQuestion(id: 'mg9_6_3', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 5,
    questionText: 'TÜRKPATENT tarafından tescil edilen bir \'Marka Tescil Belgesi\'nin yasal koruma süresi kaç yıldır ve bu süre uzatılabilir mi?',
