  QuizQuestion(id: 'mg9_6_5', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 5,
    questionText: 'Türkiye\'de 6769 Sayılı Sınai Mülkiyet Kanunu\'na göre incelemeli bir \'Patent\' tescilinin koruma süresi kaç yıldır ve bu süre uzatılabilir mi?',
