  QuizQuestion(id: 'mg9_6_6', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 5,
    questionText: 'Patent kriterlerine göre \'buluş basamağı\' içermeyen ancak yeni olan ve sanayiye uygulanabilen teknik cihaz ve ürün geliştirmelerine verilen 10 yıllık tescil belgesi hangisidir?',
    options: ['Marka Tescili', 'Faydalı Model Belgesi', 'Telif Hakkı', 'Bandrol Belgesi'],
