  // ÜNİTE 7: TEKNOLOJİK GELİŞMELER VE ENDÜSTRİYEL DÖNÜŞÜM (16 Soru)
  QuizQuestion(id: 'mg9_7_1', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 6,
