  QuizQuestion(id: 'mg9_7_2', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 6,
    questionText: 'Otel odalarındaki klima, aydınlatma, televizyon ve kapı kilitlerinin internete bağlanarak birbiriyle veri alışverişinde bulunmasını ve uzaktan kontrol edilmesini sağlayan teknolojiye ne ad verilir?',
