  QuizQuestion(id: 'mg9_7_4', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 6,
    questionText: 'Bir seyahat acentesinde çalışan personelin e-posta adresine gelen \'Banka şifreniz kilitlendi, hesabınızı kurtarmak için buraya tıklayın\' mesajındaki sahte bağlantıya tıklaması hangi siber saldırı türüne örnektir?',
