  QuizQuestion(id: 'mg9_7_5', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 6,
    questionText: 'Türkiye\'de 6698 Sayılı Kişisel Verilerin Korunması Kanunu\'na (KVKK) göre, bir otelin misafirlerin kimlik ve iletişim bilgilerini saklaması ve işlemesi için alması gereken en temel yasal onay hangisidir?',
