  QuizQuestion(id: 'mg9_7_8', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 6,
    questionText: 'Bir otel işletmesinin sunucularını ve rezervasyon yazılımlarını kendi bodrum katındaki bilgisayarlarda tutmak yerine internet üzerinden küresel veri merkezlerinde barındırması hangi bilişim modelidir?',
