  QuizQuestion(id: 'mg9_7_9', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 6,
    questionText: 'Karmaşık algoritmaları kullanarak insan zekasını taklit eden, misafirlerin sorularını doğal dilde yanıtlayan ve 7/24 hizmet veren akıllı yazılımlara ne ad verilir?',
    options: ['Yapay Zekâ ve Üretken Sohbet Robotları (Chatbot)', 'Antivirüs Programı', 'Veritabanı Tablosu', 'Güvenlik Duvarı (Firewall)'],
    correctOptionIndex: 0,
    explanation: 'Doğal dil işleme ve öğrenme algoritmalarıyla çalışan sistemler \'Yapay Zekâ (AI) ve Chatbot\' teknolojileridir.',
  ),
  QuizQuestion(id: 'mg9_7_10', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 6,
    questionText: 'Büyük veri (Big Data) kavramını tanımlayan ve \'5V\' olarak bilinen temel nitelikler arasında aşağıdakilerden hangisi yer alır?',
    options: ['Yalnızca Donanım, Yazılım ve Ağ Hızı', 'Hacim, Hız, Çeşitlilik, Doğruluk ve Değer (5V)', 'Görünürlük, Güvenlik, Gizlilik ve İtibar', 'Yalnızca Muhasebe, Bütçe ve Maliyet Hesabı'],
    correctOptionIndex: 1,
    explanation: 'Büyük verinin 5V\'si: Volume (Hacim), Velocity (Hız), Variety (Çeşitlilik), Veracity (Doğruluk/Güvenilirlik) ve Value (Değer)\'dur.',
  ),
  QuizQuestion(id: 'mg9_7_11', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 6,
    questionText: 'Kişisel ve kurumsal dijital güvenliği sağlamak amacıyla personelin alması gereken en temel \'Siber Hijyen\' önlemi hangisidir?',
    options: ['Her hesap için \'123456\' gibi kolay şifreler belirlemek', 'Şifreleri monitörün altına post-it ile yapıştırmak', 'Güçlü ve benzersiz parolalar kullanıp iki adımlı doğrulamayı (2FA) etkinleştirmek', 'Gelen her e-posta ekini kontrol etmeden hemen indirmek'],
