  // ÜNİTE 9: YEŞİL DÖNÜŞÜM, DİJİTAL DÖNÜŞÜM VE İKİZ DÖNÜŞÜM (16 Soru)
  QuizQuestion(id: 'mg9_9_1', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 8,
    questionText: 'Sürdürülebilir bir gelecek için çevreci (yeşil) uygulamalar ile ileri teknolojilerin (dijitalleşme) eş zamanlı ve birbirini destekleyecek şekilde entegre edilmesine ne ad verilir?',
