  QuizQuestion(id: 'mg9_9_4', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 8,
    questionText: 'Kurumların yalnızca finansal kârlarını değil; doğaya etkilerini, toplumsal faydalarını ve kurumsal şeffaflıklarını ölçen uluslararası sürdürülebilirlik kriterleri kısaltması hangisidir?',
