  QuizQuestion(id: 'mg9_9_5', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 8,
    questionText: 'Tasarım aşamasından itibaren bir ürünün tüm parçalarının doğaya biyolojik besin veya sanayiye teknik hammadde olarak geri dönecek şekilde planlandığı \'Beşikten Beşiğe\' felsefesinin adı nedir?',
