  QuizQuestion(id: 'mg9_9_6', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 8,
    questionText: 'Bir otelde odalardaki enerji, klima ve aydınlatma sistemlerinin IoT sensörleri ile merkezi bina yönetim sistemi (BMS) tarafından optimize edilerek karbon salımının düşürülmesi hangi kavramın somut örneğidir?',
