  QuizQuestion(id: 'mg9_9_7', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 8,
    questionText: 'Tüketicilere veya işletmelere bir cihazın mülkiyetini satmak yerine, o cihazın sağladığı faydayı (örneğin aydınlatmayı veya soğutmayı) hizmet olarak sunan döngüsel iş modeline ne ad verilir?',
