  QuizQuestion(id: 'mg9_9_8', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 8,
    questionText: 'Bir ürünün hammadde tedarikinden kullanım ömrü sonuna kadar karbon emisyonu, tamir edilebilirlik ve geri dönüştürülmüş içerik bilgilerini içeren dijital kimlik kartına ne denir?',
