  QuizQuestion(id: 'mg9_9_9', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 8,
    questionText: 'Bir işletmenin aslında çevreye zararlı üretim yaparken, sadece reklam ve halkla ilişkiler yoluyla kendini doğa dostu ve yeşil göstermeye çalışmasına ne ad verilir?',
