  QuizQuestion(id: 'mg9_9_10', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 8,
    questionText: 'Güneş ve rüzgardan üretilen elektriği talebin yoğun olduğu saatlere akıllı algoritmalarla yönlendiren iki yönlü elektrik şebekelerine ne denir?',
