  QuizQuestion(id: 'mg9_9_11', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 8,
    questionText: 'Turizm işletmelerinde kâğıt menü, basılı broşür ve basılı fatura kullanımını kaldırıp her şeyin karekod ve e-fatura sistemine aktarılması ikiz dönüşüme nasıl katkı sağlar?',
    options: ['Sadece misafirlerin kafasını karıştırır', 'Maliyetleri aşırı derecede artırır', 'Hem ağaç kesimini ve atığı önler (Yeşil) hem de hızlı veri akışı sağlar (Dijital)', 'Hiçbir çevresel fayda üretmez'],
    correctOptionIndex: 2,
    explanation: 'Dijitalleşme sayesinde kağıt israfı ve karbon salımı önlenir; bu da tam anlamıyla yeşil ve dijital bütünleşmedir.',
