  QuizQuestion(id: 'mg9_9_12', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 8,
    questionText: 'Avrupa Yeşil Mutabakatı kapsamında Türkiye\'den AB ülkelerine demir-çelik, çimento, alüminyum gibi ürün ihraç eden firmaların yüksek emisyon nedeniyle karşılaşacağı yeni mali yükümlülük hangisidir?',
