  QuizQuestion(id: 'mg9_10_1', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 9,
    questionText: 'Bireylerin parayı yönetme, bütçe yapma, tasarruf ve yatırım kararları alabilme, finansal riskleri anlayarak doğru kararlar verebilme bilgi ve becerisine ne ad verilir?',
