    options: ['Borç tamamen sıfırlanır ve kredi puanı hızla yükselir', 'Kalan ana paraya her ay yüksek gecikme ve akdi faiz binerek borç çığ gibi büyür', 'Banka tüm borcu hibe eder', 'Hiçbir faiz işlemez'],
