  QuizQuestion(id: 'mg9_10_8', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 9,
    questionText: 'Türkiye\'de Kredi Kayıt Bürosu (KKB) tarafından bireylerin kredi, kredi kartı ve fatura ödeme alışkanlıkları puanlanarak hesaplanan nota ne ad verilir?',
