    options: ['Sağlıklı beslenme, barınma (kira) ve zorunlu ulaşım giderleri', 'Son model akıllı cep telefonunu modeli eskidi diye değiştirmek', 'Haftada üç gün lüks restoranda yemek yemek', 'Marka spor ayakkabı koleksiyonu yapmak'],
