  QuizQuestion(id: 'mg9_10_15', courseId: 'mesleki_gelisim_atolyesi', unitIndex: 9,
    questionText: 'Bir yatırımcının satın aldığı finansal varlığı dilediği an piyasada değer kaybına uğramadan hızlıca nakit paraya dönüştürebilme kolaylığına ne denir?',
