  QuizQuestion(id: 'kg10_1_9', courseId: 'konuk_giris_cikis_islemleri', unitIndex: 0,
    questionText: 'Görüşmenin son aşamasında kararsızlığı giderip misafirin oda satış onayını resmiyete kavuşturma adımına ne denir?',
