  QuizQuestion(id: 'obh_u4_2', courseId: 'on_buro_hizmetleri_atolyesi', unitIndex: 3,
    questionText: 'Bir otel faturasında KDV dahil tutar 3.300 TL\'dir. KDV oranı %10 olduğuna göre matrah (KDV hariç tutar) kaç TL\'dir?',
    options: ['3.000 TL', '3.100 TL', '2.900 TL', '2.800 TL'],
