  QuizQuestion(id: 'obh_u4_5', courseId: 'on_buro_hizmetleri_atolyesi', unitIndex: 3,
    questionText: 'Rack rate (liste fiyatı) 4.000 TL olan bir süit odaya %15 acente indirimi yapılırsa indirimli satış fiyatı kaç TL olur?',
