  QuizQuestion(id: 'obh_u4_8', courseId: 'on_buro_hizmetleri_atolyesi', unitIndex: 3,
    questionText: '%2 Konaklama Vergisi dahil tutarı 10.200 TL olan bir faturanın vergi hariç matrahı kaç TL\'dir?',
