  QuizQuestion(id: 'obh_u4_9', courseId: 'on_buro_hizmetleri_atolyesi', unitIndex: 3,
    questionText: 'Bir seyahat acentesi sattığı 10.000 TL\'lik otel rezervasyonu üzerinden %12 komisyon alacaktır. Acentenin alacağı komisyon tutarı kaç TL\'dir?',
