  QuizQuestion(id: 'obh_u4_12', courseId: 'on_buro_hizmetleri_atolyesi', unitIndex: 3,
    questionText: '5 gece kalıp 4 gece öde kampanyasıyla konaklayan bir misafirin normal gecelik fiyatı 2.000 TL ise toplamda yaptığı indirim yüzdesi kaçtır?',
