  QuizQuestion(id: 'obh_u4_13', courseId: 'on_buro_hizmetleri_atolyesi', unitIndex: 3,
    questionText: '6.000 TL tutarındaki konaklama hizmetine %10 sadakat indirimi uygulanacak ve kalan net matrah üzerinden %10 KDV eklenecektir. Konuğun ödeyeceği toplam tutar kaç TL\'dir?',
