  QuizQuestion(id: 'obh_u4_14', courseId: 'on_buro_hizmetleri_atolyesi', unitIndex: 3,
    questionText: 'Otelin 100 satılabilir odasından 70\'i satılmış ve toplam oda geliri 140.000 TL olmuştur. Satılan odaların ortalama fiyatı (ADR) kaç TL\'dir?',
