  QuizQuestion(id: 'obh_u4_15', courseId: 'on_buro_hizmetleri_atolyesi', unitIndex: 3,
    questionText: 'Bir gruptan 5.000 TL kaparo (deposit) alınmıştır. Konaklama sonu toplam fatura 18.000 TL çıktığına göre çıkışta tahsil edilecek kalan bakiye kaç TL\'dir?',
