  QuizQuestion(id: 'obh_u5_8', courseId: 'on_buro_hizmetleri_atolyesi', unitIndex: 4,
    questionText: 'Acentenin 50.000 TL tutarındaki brüt satışına %10 acente komisyonu ve %20 KDV uygulanacaktır. Acenteye ödenecek net komisyon tutarı kaç TL\'dir?',
