    questionText: 'Fatura matrahı 8.000 TL olan bir konaklama işleminde %10 KDV ve %2 Konaklama Vergisi toplam vergi tutarı kaç TL\'dir?',
    options: ['800 TL', '900 TL', '960 TL', '1.000 TL'],
    correctOptionIndex: 2,
    explanation: 'KDV = 800 TL, Konaklama Vergisi = 160 TL. Toplam Vergi = 960 TL.',
