  QuizQuestion(id: 'obh_u5_11', courseId: 'on_buro_hizmetleri_atolyesi', unitIndex: 4,
    questionText: 'Bir otelin 1 günde döviz kasasına giren 2.000 Dolar (kur: 30 TL) ve 1.000 Euro (kur: 33 TL) parasının toplam TL karşılığı nedir?',
