  QuizQuestion(id: 'obh_u6_1', courseId: 'on_buro_hizmetleri_atolyesi', unitIndex: 5,
    questionText: 'Otelin satılan oda sayısının, toplam satılabilir oda sayısına bölünmesiyle elde edilen temel istatistiki oran hangisidir?',
