    correctOptionIndex: 0,
    explanation: 'Oda Doluluk Oranı = Satılan Oda Sayısı / Satılabilir Oda Sayısı x 100 formülüyle bulunur.',
  ),
  QuizQuestion(id: 'obh_u6_2', courseId: 'on_buro_hizmetleri_atolyesi', unitIndex: 5,
