    correctOptionIndex: 1,
    explanation: 'ADR = Toplam Oda Geliri / Satılan Oda -> 300.000 / 150 = 2.000 TL.',
  ),
  QuizQuestion(id: 'obh_u6_6', courseId: 'on_buro_hizmetleri_atolyesi', unitIndex: 5,
    questionText: '100 odalı bir otel bir günde 80 oda satmış ve 160.000 TL oda geliri elde etmiştir. Bu otelin RevPAR değeri kaç TL\'dir?',
