  QuizQuestion(id: 'obh_u6_7', courseId: 'on_buro_hizmetleri_atolyesi', unitIndex: 5,
    questionText: 'Otelde 100 oda satılmış ve bu odalarda toplam 180 misafir konaklamıştır. Çift kişilik işgal (Double Occupancy) oranı nedir?',
